Here’s an example using **Express**, **Multer**, and **Sharp**. It checks the image’s decoded content, limits the upload to 5 MB, and generates the stored filename on the server.

```bash
npm install express multer sharp
```

```js
const express = require("express");
const multer = require("multer");
const sharp = require("sharp");
const crypto = require("node:crypto");
const fs = require("node:fs/promises");
const path = require("node:path");

const app = express();
const uploadDir = path.join(__dirname, "uploads", "profile-pictures");

const upload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: 5 * 1024 * 1024, // 5 MB
    files: 1,
  },
});

// Add your authentication middleware to this route.
app.post("/api/profile-picture", upload.single("picture"), async (req, res, next) => {
  if (!req.file) {
    return res.status(400).json({ error: "Choose an image to upload." });
  }

  let imageBuffer;
  try {
    const image = sharp(req.file.buffer, {
      limitInputPixels: 20_000_000,
      failOn: "error",
    });

    const metadata = await image.metadata();

    // Checked from the image content, not the filename or MIME type.
    if (!["jpeg", "png", "webp"].includes(metadata.format)) {
      return res.status(400).json({ error: "Use a JPEG, PNG, or WebP image." });
    }

    // Decode and re-encode rather than storing the original upload.
    imageBuffer = await image
      .rotate()
      .resize(512, 512, { fit: "cover", withoutEnlargement: true })
      .webp({ quality: 85 })
      .toBuffer();
  } catch {
    return res.status(400).json({ error: "Invalid or unsupported image." });
  }

  try {
    await fs.mkdir(uploadDir, { recursive: true });
    const filename = `${crypto.randomUUID()}.webp`;
    await fs.writeFile(path.join(uploadDir, filename), imageBuffer, { flag: "wx" });

    // Associate filename with the authenticated user in your database here.
    res.status(201).json({ filename });
  } catch (err) {
    next(err);
  }
});

app.use((err, req, res, next) => {
  if (err instanceof multer.MulterError) {
    return res.status(400).json({
      error: err.code === "LIMIT_FILE_SIZE" ? "Image exceeds 5 MB." : "Invalid upload.",
    });
  }
  next(err);
});

app.listen(3000);
```

A basic form can submit the file as `multipart/form-data`:

```html
<form action="/api/profile-picture" method="post" enctype="multipart/form-data">
  <input type="file" name="picture" accept="image/jpeg,image/png,image/webp" required>
  <button type="submit">Upload</button>
</form>
```

Connect the route to your authentication and user database before deploying. If you use cookie-based authentication, also apply your site’s CSRF protection. The `accept` attribute improves the file picker, but the server-side checks enforce the restriction.

